-- 065_seed_original_plan_content.sql — day + exercise content for the six original plans.
-- Plans 40-45 (Foundations of Strength, Iron Forge Protocol, Fat Loss Sprint,
-- Cardio Surge, Mobility Reset, Total Flexibility Flow) were inserted by 030_seeds.sql
-- with NO plan_contents, so on a fresh/deployed database opening them returned
-- 404 PLAN_NOT_FOUND ("Could not open this plan"). Their days only existed in the
-- old phpMyAdmin dump. Idempotent: a plan that already has days is left alone,
-- and exercises are added only to days that have none. Matches plans by title.

INSERT INTO plan_contents (plan_id, day_number, title, activity_type, description, duration_mins)
SELECT p.id, v.day_number, v.title, v.activity_type, v.description, v.duration_mins
FROM plans p
JOIN (
SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 1 AS day_number, 'Week 1: Full-Body Strength A' AS title, 'Strength' AS activity_type, 'Squat, bench press, and bent-over row at light, controlled loads to groove the core movement patterns.' AS description, 45 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 2 AS day_number, 'Week 1: Mobility & Core' AS title, 'Mobility' AS activity_type, 'Hip, shoulder, and ankle mobility drills paired with a basic anti-rotation core circuit.' AS description, 25 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 3 AS day_number, 'Week 1: Full-Body Strength B' AS title, 'Strength' AS activity_type, 'Deadlift, overhead press, and pull-up (or assisted row) variations focusing on bracing and bar path.' AS description, 45 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 4 AS day_number, 'Week 1: Active Recovery Walk' AS title, 'Recovery' AS activity_type, 'A brisk outdoor or treadmill walk to promote blood flow and aid recovery between lifting days.' AS description, 30 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 5 AS day_number, 'Week 1: Full-Body Strength C' AS title, 'Strength' AS activity_type, 'Front squat, incline press, and single-arm row to round out weekly volume with fresh angles.' AS description, 45 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 6 AS day_number, 'Week 1: Conditioning Circuit' AS title, 'Cardio' AS activity_type, 'Light kettlebell or bodyweight circuit to build work capacity without interfering with strength gains.' AS description, 30 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 7 AS day_number, 'Week 1: Rest Day' AS title, 'Recovery' AS activity_type, 'Full rest. Prioritize sleep, hydration, and protein intake to support muscle repair.' AS description, 10 AS duration_mins
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 8 AS day_number, 'Week 2: Full-Body Strength A' AS title, 'Strength' AS activity_type, 'Squat, bench press, and bent-over row at light, controlled loads to groove the core movement patterns.' AS description, 45 AS duration_mins
