INSERT INTO plan_exercises (plan_content_id, exercise_order, exercise_name, sets, reps, duration_seconds, rest_seconds, notes)
SELECT pc.id, v.exercise_order, v.exercise_name, v.sets, v.reps, v.duration_seconds, v.rest_seconds, v.notes
FROM plans p
JOIN plan_contents pc ON pc.plan_id = p.id
JOIN (
SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 1 AS day_number, 1 AS exercise_order, 'Barbell Back Squat' AS exercise_name, 3 AS sets, '10' AS reps, NULL AS duration_seconds, 90 AS rest_seconds, 'Controlled tempo, focus on depth' AS notes
UNION ALL SELECT 'Foundations of Strength' COLLATE utf8mb4_unicode_ci AS ptitle, 1 AS day_number, 2 AS exercise_order, 'Flat Barbell Bench Press' AS exercise_name, 3 AS sets, '10' AS reps, NULL AS duration_seconds, 90 AS rest_seconds, NULL AS notes
